SELECT sale_cohort, product_id, units_count FROM (SELECT CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, product_id, COUNT(units) AS units_count FROM store_sales GROUP BY CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END, product_id) AS x WHERE units_count > 8 ORDER BY product_id, sale_cohort LIMIT 5;
